/* Xhosa Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Thandiwe": "beloved — Xhosa thanda (love)", "Sipho": "gift — Xhosa", "Nomvula": "mother of rain — Xhosa mvula (rain)", "Mandla": "strength, power — Nguni", "Lungile": "it is good, it is right — Xhosa lunga (be good/right)", "Nkosazana": "princess — Xhosa inkosi (chief) + -azana", "Mandela": "Clan name of Nelson Mandela; Xhosa speakers address him by the clan praise name Madiba.", "Sisulu": "Family name of Walter Sisulu, the anti-apartheid leader.", "Mbeki": "Family name of Thabo Mbeki, former president of South Africa.", "Tutu": "Family name of Archbishop Desmond Tutu."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Thandiwe';
console.log(lookup(q));

